corrected_code:
router.delete('/api/auth/token-family/:familyId/revoke', requireAuth, async (req, res) => {
  const { familyId } = req.params;

  const deletedCount = await RefreshTokenFamily.destroy({
    where: { id: familyId, userId: req.user.id }
  });

  if (!deletedCount) {
    return res.status(403).json({ message: 'Token family not found or access denied' });
  }

  return res.json({ success: true, revokedFamilyId: familyId });
});
